export function inputToShipInput(input: InputPayload): ShipInput {
  return {
    thrust: input.thrust,
    yaw: input.yaw,
    pitch: input.pitch,
    roll: input.turn,
    up: input.action === 'vtol' ? 1 : 0,
  };
