  return {
    seq,
    thrust: input.thrust,
    yaw: input.yaw,
    pitch: input.pitch,
    turn: input.roll,
    fire: false,
    lock: false,
    ...(input.up > 0 ? { action: 'vtol' } : {}),
  };
}

